// generar_288_flechas_triangulares_desplegar.js
// CHIQUI Entre Señales — Flechas de desplegar más visibles en toda la app
//
// Las flechas de las secciones desplegables eran caracteres finos
// (⌃/⌄, ▾/›) que casi no se veían. Se reemplazan en toda la app por
// TRIÁNGULOS RELLENOS sólidos (▲ abierto / ▼ cerrado), en color café
// oscuro (#8C572F), en negrita y con un tamaño legible parejo. Así se
// distinguen de un vistazo y se ven consistentes en todas las
// pantallas.
//
// Archivos afectados y nº de flechas actualizadas:
//   · app/analisis/page.tsx          (9)
//   · app/registro-diario/page.tsx   (5)
//   · app/prevencion/page.tsx        (13)
//   · components/ExamenesLab.tsx     (3)
//   · components/ExamenesLabVet.tsx  (1)
//   · components/FechaSelector.tsx   (1)
//
// NOTA: app/analisis y app/registro-diario traen además TODOS los
// cambios de esta sesión (voz de Chiqui, contenedores con fondo Estado
// de salud / Actividad física, reorden y renombres, franjas de
// alimentación, actividad acorde a tamaño/edad, fixes de edición y
// alimentación diaria, etc.). Los otros cuatro solo cambian la flecha.
//
// No hay SQL.
//
// Uso:
//   node generar_288_flechas_triangulares_desplegar.js

const fs2 = require('fs')
const path = require('path')

const archivos = [
  {
    ruta: "app/analisis/page.tsx",
    base64: ""
  },
  {
    ruta: "app/registro-diario/page.tsx",
    base64: ""
  },
  {
    ruta: "app/prevencion/page.tsx",
    base64: ""
  },
  {
    ruta: "components/ExamenesLab.tsx",
    base64: ""
  },
  {
    ruta: "components/ExamenesLabVet.tsx",
    base64: ""
  },
  {
    ruta: "components/FechaSelector.tsx",
    base64: ""
  },
]

let errores = 0
for (const a of archivos) {
  try {
    const rutaCompleta = path.join(process.cwd(), a.ruta)
    fs2.mkdirSync(path.dirname(rutaCompleta), { recursive: true })
    const contenido = Buffer.from(a.base64, 'base64').toString('utf8')
    fs2.writeFileSync(rutaCompleta, contenido, 'utf8')
    console.log('OK: ' + a.ruta)
  } catch (e) {
    errores++
    console.error('ERROR escribiendo ' + a.ruta + ': ' + e.message)
  }
}

if (errores === 0) {
  console.log('\nListo. 6 archivos escritos. git add / commit / push.')
} else {
  console.error('\nTerminó con ' + errores + ' error(es). NO hagas push.')
  process.exit(1)
}
